// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount, uint256 initialFunding) public {
        initialFunding = bound(initialFunding, 0, 1 ether);
        amount = bound(amount, 0, 1 ether);

        address attacker = address(new Reverter());

        vm.deal(address(this), initialFunding);
        (bool s,) = address(c).call{value: initialFunding}("");
        require(s);

        uint256 before = address(c).balance;

        ReverterDeployer rd = new ReverterDeployer();
        SimpleWallet c2 = rd.deployC();

        vm.deal(address(this), initialFunding);
        (bool s2,) = address(c2).call{value: initialFunding}("");
        require(s2);
        uint256 before2 = address(c2).balance;

        uint256 amt = amount;
        if (amt > before2) amt = before2;

        bool ok = rd.callWithdraw(address(c2), amt);

        uint256 after2 = address(c2).balance;
        assertTrue(!(ok && after2 != before2 - amt));
    }
}

contract Reverter {
    receive() external payable {
        revert("no receive");
    }
    fallback() external payable {
        revert("no fallback");
    }
}

contract ReverterDeployer {
    SimpleWallet public c;
    function deployC() external returns (SimpleWallet) {
        c = new SimpleWallet();
        return c;
    }
    function callWithdraw(address target, uint256 amt) external returns (bool) {
        try SimpleWallet(payable(target)).withdraw(amt) {
            return true;
        } catch {
            return false;
        }
    }
}
